icash_claim_before_activation:
CREATE OR REPLACE FUNCTION public.icash_claim_before_activation(p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare b public.icash_operating_budget; o public.icash_operation_spend; r public.icash_operation_rates; a public.icash_accounts;
begin
 select * into b from public.icash_operating_budget where id=1 for update;
 select * into o from public.icash_operation_spend where operation_key=p_operation for update;
 if not found or o.state<>'reserved' or not b.enabled or (b.require_company_reserve and b.funded_micros::numeric-b.spent_micros-b.protected_micros<b.reserved_micros) then return false; end if;
 select * into a from public.icash_accounts where id=o.account_id for update;
 select * into r from public.icash_operation_rates where id=o.rate_id for share;
 if exists(select 1 from public.icash_voice_jobs j where j.account_id=o.account_id and 'voice:'||j.id=p_operation
  and j.meta_followup_lead_id is not null and not public.icash_meta_followup_current(j.meta_followup_lead_id,'call'))
 or exists(select 1 from public.icash_meta_lead_messages mm join public.icash_text_messages msg on msg.id=mm.message_id
  where msg.account_id=o.account_id and 'text:'||msg.id=p_operation and mm.purpose in ('followup_1','followup_2')
  and not public.icash_meta_followup_current(mm.lead_id,mm.purpose)) then return false;end if;

 if (a.bot_paused and not public.icash_general_reception_pause_exempt(o.account_id,p_operation,o.charge_cap_cents) and not public.icash_customer_text_operation(o.account_id,p_operation)) or not r.enabled or r.expires_at<=now() or o.permission_until<=now() then return false; end if;
 if r.operation='seller_call' and not public.icash_limited_seller_voice(o.account_id,p_operation) and not public.icash_cancellation_voice_current(o.account_id,p_operation) and not exists(select 1 from public.icash_voice_jobs meta_job where meta_job.account_id=o.account_id and 'voice:'||meta_job.id=p_operation and public.icash_meta_voice_context(o.account_id,meta_job.id) is not null) and (o.financial_checked_at is null or o.financial_checked_at<now()-interval '24 hours') then return false; end if;
 update public.icash_operation_spend set state='dispatched',dispatched_at=now() where operation_key=p_operation;
 return true;
end $function$

icash_claim_before_membership:
CREATE OR REPLACE FUNCTION public.icash_claim_before_membership(p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a uuid;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 if exists(select 1 from public.icash_operating_budget where id=1 and not require_company_reserve) then
 select account_id into a from public.icash_operation_spend where operation_key=p_operation;
 if not exists(select 1 from public.icash_spend_activations where account_id=a and enabled) then return false;end if;
 end if;
 return public.icash_claim_before_activation(p_operation);
end $function$

icash_claim_operation:
CREATE OR REPLACE FUNCTION public.icash_claim_operation(p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a uuid;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select account_id into a from public.icash_operation_spend where operation_key=p_operation;
 if not public.icash_membership_work_allowed(a) then return false;end if;
 perform 1 from public.icash_wallets where account_id=a and balance_cents>0 for update;
 if not found then return false;end if;
 return public.icash_claim_before_membership(p_operation);
end $function$

icash_hold_voice_job:
CREATE OR REPLACE FUNCTION public.icash_hold_voice_job(p_account uuid, p_job uuid, p_reason text, p_after_claim boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_voice_jobs;o public.icash_operation_spend;
begin
 if p_reason is null or length(p_reason) not between 1 and 200 or p_after_claim is null then raise exception 'Invalid hold';end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into j from public.icash_voice_jobs where id=p_job and account_id=p_account for update;
 if not found or j.state<>(case when p_after_claim then 'dispatching' else 'issued' end) then return false;end if;
 if not p_after_claim then
  select * into o from public.icash_operation_spend where operation_key='voice:'||j.id and account_id=p_account for update;
  if found then
   if o.state='reserved' then perform public.icash_settle_operation(o.operation_key,0,0,'Voice stopped before provider dispatch: '||p_reason);
   elsif o.state<>'cancelled' then return false;end if;
  end if;
 end if;
 update public.icash_voice_jobs set state='held',outcome=p_reason,updated_at=now() where id=j.id;
 return true;
end $function$

icash_meta_claim_voice:
CREATE OR REPLACE FUNCTION public.icash_meta_claim_voice(p_account uuid, p_job uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_voice_jobs;p public.icash_contact_permissions;c public.icash_voice_configs;h integer;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into j from public.icash_voice_jobs where id=p_job and account_id=p_account for update;
 if not found or j.state<>'issued' or j.due_at>now() or public.icash_meta_voice_context(p_account,p_job) is null then return false;end if;
 if not public.icash_voice_outreach_hours_current(p_account,p_job) then return false;end if;
 select * into p from public.icash_contact_permissions where id=j.permission_id and account_id=p_account for share;
 select * into c from public.icash_voice_configs where account_id=p_account and enabled and reviewed_until>now() for share;
 if c.account_id is null or not public.icash_outreach_voice_current(p_account) then return false;end if;
 h:=extract(hour from now() at time zone p.timezone);
 -- Meta voice context already verifies current inbound contact evidence.
 perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;if not found then return false;end if;
 perform pg_advisory_xact_lock(hashtextextended(p.contact_key,17));
 if exists(select 1 from public.icash_voice_jobs v join public.icash_voice_contact_targets t on t.id=coalesce(v.permission_id,v.operational_contact_id)
  where v.id<>j.id and (v.state='dispatching' or v.state='held' and v.outcome in ('provider_receipt_needs_reconciliation','provider_outcome_unknown_no_retry')) and (v.account_id=p_account or t.contact_key=p.contact_key))
  or exists(select 1 from public.icash_live_conversations where state in ('waiting','review') and (account_id=p_account or contact_key=p.contact_key)) then return false;end if;
 if not exists(select 1 from public.icash_operation_spend o join public.icash_operation_rates r on r.id=o.rate_id
  where o.operation_key='voice:'||j.id and o.account_id=p_account and o.rate_id=c.seller_rate_id and r.operation='seller_call' and r.voice_max_duration_seconds>=c.max_duration_seconds) then return false;end if;
 if not public.icash_claim_operation('voice:'||j.id) then return false;end if;
 update public.icash_voice_jobs set state='dispatching',updated_at=now(),operation_key='voice:'||id where id=j.id;
 return true;
end $function$

icash_meta_prepare_voice:
CREATE OR REPLACE FUNCTION public.icash_meta_prepare_voice(p_lead uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare m public.icash_meta_leads;l public.icash_seller_intakes;p public.icash_contact_permissions;j public.icash_voice_jobs;deal uuid;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into m from public.icash_meta_leads where lead_id=p_lead for update;
 select * into l from public.icash_seller_intakes where id=p_lead;
 if m.lead_id is null or m.paused or m.voice_paused or m.declined_at is not null or not public.icash_outreach_voice_current(m.account_id)
  or not public.icash_membership_work_allowed(m.account_id) or not exists(select 1 from public.icash_accounts where id=m.account_id and not bot_paused)
  or not exists(select 1 from public.icash_wallets where account_id=m.account_id and balance_cents>0) then return null;end if;
 select id into deal from public.icash_deal_files where account_id=m.account_id and screening_id=m.screening_id and stage='draft';
 if deal is null then return null;end if;
 perform public.icash_prepare_seller_contacts(m.account_id,m.lead_id,m.screening_id,deal);
 select * into p from public.icash_contact_permissions where account_id=m.account_id and screening_id=m.screening_id and seller_intake_id=m.lead_id and phone=l.phone and revoked_at is null;
 if p.id is null or not public.icash_seller_voice_permission_current(m.account_id,p.id) then return null;end if;
 insert into public.icash_voice_jobs(account_id,permission_id) values(m.account_id,p.id) on conflict do nothing;
 select * into j from public.icash_voice_jobs where account_id=m.account_id and permission_id=p.id and callback_id is null and sms_source_message_id is null and cancellation_notice_id is null and meta_followup_lead_id is null and meta_offer_lead_id is null and (meta_retry_of is null or id=m.voice_job_id) order by (id=m.voice_job_id) desc nulls last,created_at desc limit 1;
 if j.id is null then return null;end if;
 update public.icash_meta_leads set voice_job_id=coalesce(voice_job_id,j.id),next_attempt_at=now()+interval '1 minute' where lead_id=m.lead_id;
 if j.state<>'ready' or j.due_at>now() then return null;end if;
 update public.icash_voice_jobs set state='issued',updated_at=now() where id=j.id;
 return jsonb_build_object('accountId',m.account_id,'voiceJobId',j.id);
end $function$

icash_reserve_paced_voice:
CREATE OR REPLACE FUNCTION public.icash_reserve_paced_voice(p_account uuid, p_job uuid, p_rate uuid, p_permission_until timestamp with time zone, p_financial_checked_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_financial_eligible boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_voice_jobs;p public.icash_voice_contact_targets;r public.icash_operation_rates;a jsonb;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into j from public.icash_voice_jobs where id=p_job and account_id=p_account for update;
 if not found or j.state<>'issued' then return false;end if;
 if not public.icash_voice_outreach_hours_current(p_account,p_job) then return false;end if;
 select * into p from public.icash_voice_contact_targets where id=coalesce(j.permission_id,j.operational_contact_id) and account_id=p_account;
 select * into r from public.icash_operation_rates where id=p_rate;
 if p.id is null or p.party is distinct from 'seller' or r.id is null then return false;end if;
 if public.icash_voice_credit_bound(p_account,'voice:'||j.id,p_rate) is not null then
  r.charge_cents:=(public.icash_voice_credit_bound(p_account,'voice:'||j.id,p_rate)->>'charge_cents')::bigint;
 end if;

 if j.operational_contact_id is not null then
  if not public.icash_operational_contact_current(p_account,j.operational_contact_id,'voice',false)
   or not public.icash_claim_inventory(p_account,p.screening_id,p.phone) then return false;end if;
  p_permission_until:=least(p_permission_until,p.permission_until);
 end if;
 perform public.icash_reserve_operation(p_account,'voice:'||j.id,p_rate,p_permission_until,p_financial_checked_at,p_financial_eligible);
 return true;
end $function$
